  auto _EPOCH = _o->EPOCH.empty() ? 0 : _fbb.CreateString(_o->EPOCH);
  auto _REF_FRAME = _o->REF_FRAME.empty() ? 0 : _fbb.CreateString(_o->REF_FRAME);
  auto _X = _o->X;
  auto _Y = _o->Y;
  auto _Z = _o->Z;
  auto _X_DOT = _o->X_DOT;
  auto _Y_DOT = _o->Y_DOT;
